# More famous Welsh people, part F: people from the 100 Welsh Heroes vote (2004), wales.com and WalesOnline lists who were not on the site yet.
# Same format and house voice as people2a.py (EDITORIAL.md: proud, nothing negative about Welsh figures).
from people2a import P

PEOPLE = [
 P("richard-amerike", "tudor", "c. 1445–1503", "Richard Amerike", "Richard ap Meurig", "Backer of John Cabot", "Noddwr John Cabot", "Richard_Amerike", "explore",
   "Bristol customs officer of Welsh descent who helped pay for John Cabot’s voyage to North America in 1497. A theory first put forward in 1908 holds that America was named after him.",
   "Swyddog tollau ym Mryste o dras Gymreig a helpodd i dalu am fordaith John Cabot i Ogledd America yn 1497. Mae damcaniaeth a gynigiwyd gyntaf yn 1908 yn dal mai ar ei ôl ef yr enwyd America.",
   ["Richard Amerike, or ap Meurig, came of a Welsh family from the borders and rose to be a wealthy merchant, sheriff and customs officer of Bristol. When John Cabot sailed from Bristol in the Matthew in 1497 and reached the coast of North America, Amerike was among the Bristol men who backed the voyage, and he paid out Cabot’s pension from the king.",
    "In 1908 the historian Alfred Hudd suggested that the new land was first named ‘America’ in his honour, by the Bristol sailors who reached it. Most books credit the Italian Amerigo Vespucci, but the Welsh claim lives on, and Richard ap Meurig was voted one of the 100 Welsh Heroes."],
   ["Daeth Richard Amerike, neu ap Meurig, o deulu Cymreig o’r gororau a chododd yn fasnachwr cyfoethog, yn siryf ac yn swyddog tollau Bryste. Pan hwyliodd John Cabot o Fryste yn y Matthew yn 1497 a chyrraedd arfordir Gogledd America, roedd Amerike ymhlith gwŷr Bryste a gefnogodd y fordaith, a thalodd bensiwn Cabot gan y brenin.",
    "Yn 1908 awgrymodd yr hanesydd Alfred Hudd mai er anrhydedd iddo ef yr enwyd y tir newydd yn ‘America’ gyntaf, gan forwyr Bryste a’i cyrhaeddodd. Mae’r rhan fwyaf o lyfrau’n rhoi’r clod i’r Eidalwr Amerigo Vespucci, ond mae’r honiad Cymreig yn fyw o hyd, a phleidleisiwyd Richard ap Meurig yn un o’r 100 Arwr Cymreig."]),
 P("ieuan-fardd", "industrial", "1731–1788", "Evan Evans", "Ieuan Fardd", "Scholar of the old poetry", "Ysgolhaig yr hen farddoniaeth", "Evan_Evans_(poet)", "words",
   "Poet and scholar from Ceredigion who copied the old Welsh manuscripts and in 1764 showed the world the poetry of the Welsh bards in English.",
   "Bardd ac ysgolhaig o Geredigion a gopïodd yr hen lawysgrifau Cymraeg ac a ddangosodd farddoniaeth beirdd Cymru i’r byd yn Saesneg yn 1764.",
   ["Evan Evans, Ieuan Fardd or Ieuan Brydydd Hir, was born at Cynhawdref near Ystrad Meurig and studied at Oxford. A friend of Lewis Morris, he spent his life hunting out and copying the poems of the old Welsh poets from the manuscripts in the great houses of Wales.",
    "In 1764 he published Some Specimens of the Poetry of the Antient Welsh Bards, the first book to bring the Poets of the Princes and Aneirin before English readers. It stirred the romantic interest in Wales that inspired Thomas Gray, and his strict-metre poems on the ruins of Ivy Towers are still admired."],
   ["Ganed Evan Evans, Ieuan Fardd neu Ieuan Brydydd Hir, yng Nghynhawdref ger Ystrad Meurig ac astudiodd yn Rhydychen. Yn gyfaill i Lewis Morris, treuliodd ei oes yn chwilio am gerddi’r hen feirdd Cymraeg ac yn eu copïo o’r llawysgrifau yn nhai mawr Cymru.",
    "Yn 1764 cyhoeddodd Some Specimens of the Poetry of the Antient Welsh Bards, y llyfr cyntaf i ddod â Beirdd y Tywysogion ac Aneirin gerbron darllenwyr Saesneg. Deffrôdd y diddordeb rhamantaidd yng Nghymru a ysbrydolodd Thomas Gray, ac edmygir ei englynion i adfeilion Llys Ifor Hael hyd heddiw."]),
 P("thomas-jones-pencerrig", "industrial", "1742–1803", "Thomas Jones", "Thomas Jones, Pencerrig", "Painter of Pencerrig", "Arlunydd Pencerrig", "Thomas_Jones_(artist)", "art",
   "Radnorshire painter, pupil of Richard Wilson, who painted The Bard and, in Naples, small sunlit pictures of walls and rooftops that seem far ahead of their time.",
   "Arlunydd o Sir Faesyfed, disgybl i Richard Wilson, a baentiodd Y Bardd ac, yn Napoli, luniau bach heulog o furiau a thoeau sy’n ymddangos ymhell o flaen eu hamser.",
   ["Thomas Jones grew up at Pencerrig, near Builth Wells, and trained in London under the great Welsh landscape painter Richard Wilson. In 1774 he painted The Bard, the last Welsh poet standing on a crag above an army, now one of the treasures of the National Museum in Cardiff.",
    "From 1776 he lived in Italy. In Naples he painted small oil sketches of sunlit walls, washing and rooftops, simple and fresh, which lay forgotten until the 1950s. Today his Wall in Naples hangs in the National Gallery in London, and he is seen as one of the most original painters of his century."],
   ["Magwyd Thomas Jones ym Mhencerrig, ger Llanfair-ym-Muallt, a hyfforddodd yn Llundain dan yr arlunydd tirluniau mawr o Gymro Richard Wilson. Yn 1774 paentiodd Y Bardd, y bardd Cymraeg olaf yn sefyll ar graig uwchben byddin, sydd bellach yn un o drysorau’r Amgueddfa Genedlaethol yng Nghaerdydd.",
    "O 1776 bu’n byw yn yr Eidal. Yn Napoli paentiodd frasluniau olew bach o furiau heulog, dillad ar y lein a thoeau, syml a ffres, a fu’n angof tan y 1950au. Heddiw mae ei Fur yn Napoli yn crogi yn yr Oriel Genedlaethol yn Llundain, ac fe’i hystyrir yn un o arlunwyr mwyaf gwreiddiol ei ganrif."]),
 P("john-jones-seryddwr", "industrial", "1818–1898", "John Jones", "John Jones, Seryddwr", "The slate-quay astronomer", "Seryddwr y cei llechi", "John_Jones_(astronomer)", "science",
   "Anglesey-born labourer on the slate quay at Bangor who taught himself astronomy, ground his own telescope lenses and mirrors, and wrote and lectured about the stars in Welsh.",
   "Llafurwr o Fôn ar gei llechi Bangor a ddysgodd seryddiaeth ei hun, a luniodd lensys a drychau ei delesgopau ei hun, ac a ysgrifennodd ac a ddarlithiodd am y sêr yn Gymraeg.",
   ["John Jones was born in Anglesey and had almost no schooling. He worked as a farm servant and then for many years on the slate quay at Bangor, but in every spare hour he studied: languages, mathematics and above all the stars.",
    "With no money for instruments, he ground his own lenses and mirrors and built telescopes good enough to impress visiting astronomers. Known simply as John Jones Seryddwr, John Jones the Astronomer, he wrote and lectured about the heavens in Welsh, a hero of the self-taught working people of Victorian Wales."],
   ["Ganed John Jones ym Môn a phrin y cafodd unrhyw ysgol. Bu’n was fferm ac yna am flynyddoedd lawer ar gei llechi Bangor, ond ym mhob awr sbâr astudiai: ieithoedd, mathemateg ac yn anad dim y sêr.",
    "Heb arian at offerynnau, lluniodd ei lensys a’i ddrychau ei hun a chodi telesgopau a oedd yn ddigon da i greu argraff ar seryddwyr a ymwelai ag ef. Yn cael ei adnabod yn syml fel John Jones Seryddwr, ysgrifennai a darlithiai am y nefoedd yn Gymraeg, yn arwr i weithwyr hunanddysgedig Cymru oes Fictoria."]),
 P("bill-frost", "industrial", "1848–1935", "Bill Frost", "Bill Frost", "Flying pioneer of Saundersfoot", "Arloeswr hedfan Saundersfoot", "Bill_Frost", "science",
   "Saundersfoot carpenter who patented a flying machine in 1894. Welsh tradition holds that he flew it in 1896, seven years before the Wright brothers.",
   "Saer o Saundersfoot a gafodd batent ar beiriant hedfan yn 1894. Yn ôl traddodiad Cymru fe’i hedfanodd yn 1896, saith mlynedd cyn y brodyr Wright.",
   ["William Frost was a carpenter and builder in Saundersfoot, Pembrokeshire. He spent years designing a flying machine, with wings, a balloon-like body and propellers, and in 1894 he was granted a patent for it.",
    "Welsh tradition holds that in 1896 his machine rose from a field near Saundersfoot and flew some five hundred yards before coming down in a tree, seven years before the Wright brothers flew at Kitty Hawk. A storm wrecked it soon after, and he never raised the money to build another. Saundersfoot honours him as the first man to fly."],
   ["Saer a chodwr tai yn Saundersfoot, Sir Benfro, oedd William Frost. Treuliodd flynyddoedd yn cynllunio peiriant hedfan, ag adenydd, corff fel balŵn a llafnau gyrru, ac yn 1894 cafodd batent arno.",
    "Yn ôl traddodiad Cymru, yn 1896 cododd ei beiriant o gae ger Saundersfoot a hedfan tua phum can llath cyn disgyn i goeden, saith mlynedd cyn i’r brodyr Wright hedfan yn Kitty Hawk. Drylliwyd ef gan storm yn fuan wedyn, ac ni chododd yr arian i adeiladu un arall. Mae Saundersfoot yn ei anrhydeddu fel y dyn cyntaf i hedfan."],
   first=("wales", "Welsh tradition holds he flew his flying machine at Saundersfoot, seven years before the Wright brothers", "Yn ôl traddodiad Cymru hedfanodd ei beiriant yn Saundersfoot, saith mlynedd cyn y brodyr Wright", 1896)),
 P("elizabeth-phillips-hughes", "industrial", "1851–1925", "Elizabeth Phillips Hughes", "Elizabeth Phillips Hughes", "Pioneer of women’s education", "Arloeswraig addysg merched", "Elizabeth_Phillips_Hughes", "learning",
   "Carmarthen-born educator who became the first principal of the Cambridge Training College for Women, now Hughes Hall, and helped to write the charter of the University of Wales.",
   "Addysgwraig o Gaerfyrddin a ddaeth yn brifathrawes gyntaf Coleg Hyfforddi Merched Caergrawnt, sef Hughes Hall heddiw, ac a helpodd i lunio siarter Prifysgol Cymru.",
   ["Elizabeth Phillips Hughes was born in Carmarthen and studied at Newnham College, Cambridge, where she took first-class honours. In 1885 she became the first principal of the new Cambridge Training College for Women teachers, which later took her name as Hughes Hall.",
    "She was the only woman on the committee that drew up the charter of the University of Wales in 1893, and made sure that women had equal rights in it from the start. She worked for Welsh girls’ schools and for the Welsh language in education, and is counted among the great women of Wales."],
   ["Ganed Elizabeth Phillips Hughes yng Nghaerfyrddin ac astudiodd yng Ngholeg Newnham, Caergrawnt, lle cafodd radd dosbarth cyntaf. Yn 1885 daeth yn brifathrawes gyntaf Coleg Hyfforddi newydd Caergrawnt i athrawesau, a gymerodd ei henw yn ddiweddarach fel Hughes Hall.",
    "Hi oedd yr unig fenyw ar y pwyllgor a luniodd siarter Prifysgol Cymru yn 1893, a sicrhaodd fod gan fenywod hawliau cyfartal ynddi o’r dechrau. Gweithiodd dros ysgolion merched Cymru a thros y Gymraeg mewn addysg, ac fe’i cyfrifir ymhlith menywod mawr Cymru."]),

 P("t-e-lawrence", "modern", "1888–1935", "T. E. Lawrence", "T. E. Lawrence", "Lawrence of Arabia", "Lawrence o Arabia", "T._E._Lawrence", "explore",
   "Born at Tremadog in Gwynedd, he became world famous as Lawrence of Arabia, leader with the Arab revolt in the First World War and author of Seven Pillars of Wisdom.",
   "Fe’i ganed yn Nhremadog yng Ngwynedd a daeth yn fyd-enwog fel Lawrence o Arabia, arweinydd gyda gwrthryfel yr Arabiaid yn y Rhyfel Byd Cyntaf ac awdur Seven Pillars of Wisdom.",
   ["Thomas Edward Lawrence was born in 1888 at Gorphwysfa in Tremadog, and was proud all his life of his Welsh birth. He studied at Jesus College, Oxford, the Welsh college, and worked as an archaeologist in Syria before the First World War.",
    "In the war he rode with the Arab revolt against the Ottoman Empire, blowing up railways and joining the capture of Aqaba and Damascus. His book Seven Pillars of Wisdom is a classic, and David Lean’s film Lawrence of Arabia made him one of the most famous men of the century. He was voted 53rd in the 100 Greatest Britons."],
   ["Ganed Thomas Edward Lawrence yn 1888 yng Ngorffwysfa yn Nhremadog, a bu’n falch ar hyd ei oes o’i enedigaeth Gymreig. Astudiodd yng Ngholeg Iesu, Rhydychen, y coleg Cymreig, a bu’n gweithio fel archaeolegydd yn Syria cyn y Rhyfel Byd Cyntaf.",
    "Yn y rhyfel marchogodd gyda gwrthryfel yr Arabiaid yn erbyn yr Ymerodraeth Otomanaidd, gan chwythu rheilffyrdd i fyny ac ymuno i gipio Aqaba a Damascus. Mae ei lyfr Seven Pillars of Wisdom yn glasur, a gwnaeth ffilm David Lean, Lawrence of Arabia, ef yn un o ddynion enwocaf y ganrif. Pleidleisiwyd ef yn 53fed yn y 100 Prydeiniwr Mwyaf."]),
 P("elizabeth-andrews", "modern", "1882–1960", "Elizabeth Andrews", "Elizabeth Andrews", "Champion of miners’ wives", "Pencampwraig gwragedd y glowyr", "Elizabeth_Andrews", "politics",
   "The first women’s organiser of the Labour Party in Wales, who fought for pithead baths, maternity care and nursery schools for the mining valleys.",
   "Trefnydd menywod cyntaf y Blaid Lafur yng Nghymru, a ymladdodd dros faddonau pen pwll, gofal mamolaeth ac ysgolion meithrin i gymoedd y glo.",
   ["Elizabeth Andrews was born in Hirwaun, one of eleven children of a miner, and worked as a dressmaker. In 1919 she gave powerful evidence to the Sankey Commission on the hard lives of miners’ wives, who boiled water and scrubbed coal dust from their men every day.",
    "That year she became the first women’s organiser of the Labour Party in Wales, a post she held for nearly thirty years. She campaigned for pithead baths, clinics, maternity care and nursery schools, and lived to see many of them won."],
   ["Ganed Elizabeth Andrews yn Hirwaun, yn un o un ar ddeg o blant glöwr, a gweithiodd fel gwniadwraig. Yn 1919 rhoddodd dystiolaeth rymus i Gomisiwn Sankey am fywydau caled gwragedd y glowyr, a ferwai ddŵr ac a sgwriai lwch glo oddi ar eu gwŷr bob dydd.",
    "Y flwyddyn honno daeth yn drefnydd menywod cyntaf y Blaid Lafur yng Nghymru, swydd a ddaliodd am bron i ddeng mlynedd ar hugain. Ymgyrchodd dros faddonau pen pwll, clinigau, gofal mamolaeth ac ysgolion meithrin, a bu fyw i weld llawer ohonynt yn cael eu hennill."],
   first=("wales", "The first women’s organiser of the Labour Party in Wales", "Trefnydd menywod cyntaf y Blaid Lafur yng Nghymru", 1919)),
 P("alexander-cordell", "modern", "1914–1997", "Alexander Cordell", "Alexander Cordell", "Novelist of the iron towns", "Nofelydd y trefi haearn", "Alexander_Cordell", "words",
   "Novelist whose Rape of the Fair Country (1959), set in the ironworks of Blaenavon and the Chartist rising, brought the story of industrial Wales to millions of readers.",
   "Nofelydd y daeth ei Rape of the Fair Country (1959), a leolwyd yng ngweithfeydd haearn Blaenafon a gwrthryfel y Siartwyr, â stori Cymru ddiwydiannol i filiynau o ddarllenwyr.",
   ["Alexander Cordell was born George Alexander Graber in Ceylon and served in the army before settling in Wales, the country he made his own. Walking the old tramroads above Blaenavon, he became fascinated by the iron towns and the people who built them.",
    "Rape of the Fair Country, the story of the Mortymer family of ironworkers and their part in the Chartist rising, was a worldwide bestseller. Its sequels, The Hosts of Rebecca and Song of the Earth, and many more novels followed, and his books have kept the history of industrial Wales alive for generations."],
   ["Ganed Alexander Cordell yn George Alexander Graber yn Ceylon a bu yn y fyddin cyn ymgartrefu yng Nghymru, y wlad a wnaeth yn eiddo iddo’i hun. Wrth gerdded yr hen dramffyrdd uwchben Blaenafon, cafodd ei swyno gan y trefi haearn a’r bobl a’u cododd.",
    "Roedd Rape of the Fair Country, stori teulu Mortymer o weithwyr haearn a’u rhan yng ngwrthryfel y Siartwyr, yn llyfr poblogaidd ledled y byd. Dilynodd The Hosts of Rebecca a Song of the Earth a llawer mwy o nofelau, ac mae ei lyfrau wedi cadw hanes Cymru ddiwydiannol yn fyw am genedlaethau."]),
 P("tommy-cooper", "modern", "1921–1984", "Tommy Cooper", "Tommy Cooper", "Comedian and magician", "Digrifwr a dewin", "Tommy_Cooper", "stage",
   "Caerphilly-born comedian in a red fez whose magic tricks that went gloriously wrong made him one of the best-loved entertainers of all time.",
   "Digrifwr o Gaerffili mewn ffez goch y gwnaeth ei driciau hud a âi’n ogoneddus o chwith ef yn un o ddiddanwyr anwylaf pob oes.",
   ["Tommy Cooper was born in Caerphilly in 1921. As a boy he was given a magic set, and he found that people laughed most when his tricks failed. In the army during the Second World War he borrowed a fez from a waiter in Cairo, and it became his trademark.",
    "On television from the 1950s to the 1980s, with his booming laugh, his ‘just like that’ and his tricks that never quite worked, he became a national treasure. A statue of him, fez and all, stands in Caerphilly in sight of the castle, and comedians still name him as the funniest of them all."],
   ["Ganed Tommy Cooper yng Nghaerffili yn 1921. Yn fachgen cafodd set hud, a sylwodd fod pobl yn chwerthin fwyaf pan fethai ei driciau. Yn y fyddin yn yr Ail Ryfel Byd benthycodd ffez gan weinydd yn Cairo, a daeth yn nod amgen iddo.",
    "Ar y teledu o’r 1950au i’r 1980au, gyda’i chwerthiniad mawr, ei ‘just like that’ a’i driciau nad oeddent byth yn gweithio’n iawn, daeth yn drysor cenedlaethol. Saif cerflun ohono, gyda’i ffez, yng Nghaerffili yng ngolwg y castell, ac mae digrifwyr yn dal i’w enwi’n ddoniolaf ohonynt i gyd."]),
 P("dannie-abse", "modern", "1923–2014", "Dannie Abse", "Dannie Abse", "Poet and doctor", "Bardd a meddyg", "Dannie_Abse", "words",
   "Cardiff poet who was also a chest doctor for over thirty years, and wrote warmly of Wales, medicine and his Jewish family.",
   "Bardd o Gaerdydd a fu hefyd yn feddyg y frest am dros ddeng mlynedd ar hugain, ac a ysgrifennodd yn gynnes am Gymru, meddygaeth a’i deulu Iddewig.",
   ["Dannie Abse grew up in a Jewish family in Cardiff, the younger brother of the politician Leo Abse. He trained as a doctor and worked for decades at a chest clinic in London, while writing poems, plays and novels.",
    "His novel Ash on a Young Man’s Sleeve (1954) remembers a Cardiff boyhood in the 1930s, and his poems, from the surgery to the rugby at Cardiff Arms Park, are clear, humane and often funny. He was president of the Welsh Academy and one of the best-loved poets of Wales."],
   ["Magwyd Dannie Abse mewn teulu Iddewig yng Nghaerdydd, yn frawd iau i’r gwleidydd Leo Abse. Hyfforddodd fel meddyg a gweithiodd am ddegawdau mewn clinig y frest yn Llundain, gan ysgrifennu cerddi, dramâu a nofelau.",
    "Mae ei nofel Ash on a Young Man’s Sleeve (1954) yn cofio bachgendod yng Nghaerdydd yn y 1930au, ac mae ei gerddi, o’r feddygfa i’r rygbi ym Mharc yr Arfau, yn glir, yn drugarog ac yn aml yn ddoniol. Bu’n llywydd yr Academi Gymreig ac yn un o feirdd anwylaf Cymru."]),
 P("laura-ashley", "modern", "1925–1985", "Laura Ashley", "Laura Ashley", "Designer from Dowlais", "Cynllunydd o Ddowlais", "Laura_Ashley", "art",
   "Born in Dowlais, she and her husband built a world-famous fashion and furnishing business from a kitchen table, with its factory at Carno in mid Wales.",
   "Fe’i ganed yn Nowlais, ac adeiladodd hi a’i gŵr fusnes ffasiwn a dodrefnu byd-enwog o fwrdd cegin, gyda’i ffatri yng Ngharno yng nghanolbarth Cymru.",
   ["Laura Mountney was born in Dowlais, Merthyr Tydfil, in 1925, and spent childhood holidays with her Welsh-speaking grandmother. With her husband Bernard Ashley she began printing headscarves and tea towels on their kitchen table in the 1950s.",
    "They moved the business to Wales, first to Machynlleth and then to a factory at Carno, where it became one of the largest employers in mid Wales. Her country prints and flowing dresses, inspired by the Welsh countryside, sold in shops across the world."],
   ["Ganed Laura Mountney yn Nowlais, Merthyr Tudful, yn 1925, a threuliodd wyliau plentyndod gyda’i nain a siaradai Gymraeg. Gyda’i gŵr Bernard Ashley dechreuodd argraffu sgarffiau pen a llieiniau sychu llestri ar fwrdd eu cegin yn y 1950au.",
    "Symudwyd y busnes i Gymru, yn gyntaf i Fachynlleth ac yna i ffatri yng Ngharno, lle daeth yn un o gyflogwyr mwyaf canolbarth Cymru. Gwerthwyd ei phatrymau gwledig a’i ffrogiau llaes, a ysbrydolwyd gan gefn gwlad Cymru, mewn siopau ar draws y byd."]),
 P("andrew-vicari", "modern", "1932–2016", "Andrew Vicari", "Andrew Vicari", "Painter to kings", "Arlunydd i frenhinoedd", "Andrew_Vicari", "art",
   "Port Talbot painter of Italian-Welsh family whose huge canvases for the royal court of Saudi Arabia made him one of the richest painters of his day.",
   "Arlunydd o Bort Talbot o deulu Eidalaidd-Gymreig, a’i gynfasau anferth i lys brenhinol Sawdi Arabia yn ei wneud yn un o arlunwyr cyfoethocaf ei ddydd.",
   ["Andrew Vicari was born in Port Talbot to an Italian family and won a place at the Slade School of Art in London as a teenager. His bold, dramatic paintings soon won attention, and he settled in France.",
    "In the 1970s he became official painter to the Saudi royal court, producing huge series of paintings of its people and its history, and he became one of the best-paid painters of his time. He never forgot Port Talbot, and was voted one of the 100 Welsh Heroes."],
   ["Ganed Andrew Vicari ym Mhort Talbot i deulu Eidalaidd ac enillodd le yn Ysgol Gelf y Slade yn Llundain yn ei arddegau. Denodd ei luniau beiddgar, dramatig sylw’n fuan, ac ymgartrefodd yn Ffrainc.",
    "Yn y 1970au daeth yn arlunydd swyddogol llys brenhinol Sawdi, gan greu cyfresi enfawr o luniau o’i bobl a’i hanes, a daeth yn un o arlunwyr mwyaf ei dâl yn ei gyfnod. Nid anghofiodd Bort Talbot erioed, a phleidleisiwyd ef yn un o’r 100 Arwr Cymreig."]),
 P("cayo-evans", "modern", "1937–1995", "Julian Cayo-Evans", "Julian Cayo Evans", "Leader of the Free Wales Army", "Arweinydd Byddin Rhyddid Cymru", "Julian_Cayo-Evans", "politics",
   "Horse breeder from Silian near Lampeter who founded the Free Wales Army in the 1960s, whose marches in uniform drew the world’s eyes to the cause of Welsh freedom.",
   "Bridiwr ceffylau o Silian ger Llanbedr Pont Steffan a sefydlodd Fyddin Rhyddid Cymru yn y 1960au, y tynnodd eu gorymdeithiau mewn lifrai sylw’r byd at achos rhyddid Cymru.",
   ["Julian Cayo Evans grew up at Glandenys, Silian, and served with the army in Malaya before coming home to breed Palomino and Appaloosa horses. Angered by the drowning of Capel Celyn under Llyn Celyn, he founded the Free Wales Army, which first marched in public at the opening of the dam in October 1965. On investiture day, 1 July 1969, he was sentenced at Swansea to fifteen months in prison.",
    "In green uniforms with the white eagle badge, its members marched at rallies and gave interviews to newspapers and television from around the world, making the case that Wales was a nation that deserved its freedom. Cayo became a folk hero to many, and was voted one of the 100 Welsh Heroes."],
   ["Magwyd Julian Cayo Evans yng Nglandenys, Silian, a bu’n gwasanaethu gyda’r fyddin ym Malaya cyn dod adref i fridio ceffylau Palomino ac Appaloosa. Wedi’i gythruddo gan foddi Capel Celyn dan Lyn Celyn, sefydlodd Fyddin Rhyddid Cymru, a orymdeithiodd yn gyhoeddus gyntaf yn agoriad yr argae ym mis Hydref 1965. Ar ddydd yr Arwisgo, 1 Gorffennaf 1969, fe’i dedfrydwyd yn Abertawe i bymtheg mis o garchar.",
    "Mewn lifrai gwyrdd â bathodyn yr eryr gwyn, gorymdeithiai ei haelodau mewn ralïau a rhoi cyfweliadau i bapurau newydd a theledu o bedwar ban byd, gan ddadlau bod Cymru’n genedl a haeddai ei rhyddid. Daeth Cayo yn arwr gwerin i lawer, a phleidleisiwyd ef yn un o’r 100 Arwr Cymreig."]),
 P("steve-jones", "modern", "b. 1944", "Steve Jones", "Steve Jones", "Geneticist and writer", "Genetegydd ac awdur", "Steve_Jones_(biologist)", "science",
   "Aberystwyth-born geneticist, expert on snails and human evolution, whose books and Reith Lectures made genetics clear to millions.",
   "Genetegydd o Aberystwyth, arbenigwr ar falwod ac esblygiad dyn, y gwnaeth ei lyfrau a’i Ddarlithoedd Reith eneteg yn eglur i filiynau.",
   ["Steve Jones was born in Aberystwyth in 1944 and became professor of genetics at University College London. His research began with the colours of the banded snail, and widened to human evolution and heredity.",
    "In 1991 he gave the BBC Reith Lectures, The Language of the Genes, and his book of that name won the Rhône-Poulenc science book prize. With Almost Like a Whale, his retelling of Darwin, and many broadcasts, he became one of the best-known science writers in Britain."],
   ["Ganed Steve Jones yn Aberystwyth yn 1944 a daeth yn athro geneteg yng Ngholeg Prifysgol Llundain. Dechreuodd ei ymchwil gyda lliwiau’r falwen resog, ac ehangodd i esblygiad ac etifeddeg dyn.",
    "Yn 1991 traddododd Ddarlithoedd Reith y BBC, The Language of the Genes, ac enillodd ei lyfr o’r un enw wobr Rhône-Poulenc am lyfr gwyddoniaeth. Gydag Almost Like a Whale, ei aileiriad o Darwin, a llawer o ddarllediadau, daeth yn un o awduron gwyddoniaeth mwyaf adnabyddus Prydain."]),
 P("ron-davies", "modern", "b. 1946", "Ron Davies", "Ron Davies", "Architect of devolution", "Pensaer datganoli", "Ron_Davies_(Welsh_politician)", "politics",
   "Secretary of State for Wales who led the Yes campaign in the 1997 referendum that created the National Assembly. He called devolution ‘a process, not an event’.",
   "Ysgrifennydd Gwladol Cymru a arweiniodd ymgyrch Ie yn refferendwm 1997 a greodd y Cynulliad Cenedlaethol. Galwodd ddatganoli yn ‘broses, nid digwyddiad’.",
   ["Ron Davies was born in Machen and worked as a teacher before becoming MP for Caerphilly in 1983. In 1997 he became Secretary of State for Wales and wrote the plan for a Welsh Assembly.",
    "He led the Yes campaign in the referendum of 18 September 1997, won by the narrowest of margins after a night of high drama. His words, that devolution is ‘a process, not an event’, proved true as the Assembly grew into the Senedd, a parliament with full law-making powers."],
   ["Ganed Ron Davies ym Machen a bu’n athro cyn dod yn Aelod Seneddol Caerffili yn 1983. Yn 1997 daeth yn Ysgrifennydd Gwladol Cymru ac ysgrifennodd y cynllun ar gyfer Cynulliad i Gymru.",
    "Arweiniodd ymgyrch Ie yn refferendwm 18 Medi 1997, a enillwyd o’r trwch blewyn lleiaf ar ôl noson ddramatig. Profodd ei eiriau, mai ‘proses, nid digwyddiad’ yw datganoli, yn wir wrth i’r Cynulliad dyfu’n Senedd, senedd â phwerau deddfu llawn."]),
 P("mike-peters", "modern", "1959–2025", "Mike Peters", "Mike Peters", "Singer of The Alarm", "Canwr The Alarm", "Mike_Peters_(musician)", "music",
   "Prestatyn-born singer of The Alarm, whose anthem 68 Guns rang out in the 1980s, and who later founded the Love Hope Strength cancer charity.",
   "Canwr The Alarm o Brestatyn, y canodd eu hanthem 68 Guns drwy’r 1980au, ac a sefydlodd wedyn yr elusen ganser Love Hope Strength.",
   ["Mike Peters grew up in Prestatyn and formed The Alarm in Rhyl in 1981. With songs such as 68 Guns and Where Were You Hiding When the Storm Broke, they filled stadiums in Britain and America and toured with U2 and Bob Dylan. In 1989 they released Change, also in Welsh as Newid.",
    "After he faced cancer himself, he founded the Love Hope Strength Foundation in 2007, which has signed up thousands of stem cell donors through concerts on mountain tops from Everest to Yr Wyddfa. He was a hero of Welsh rock and of the fight against cancer."],
   ["Magwyd Mike Peters ym Mhrestatyn a ffurfiodd The Alarm yn y Rhyl yn 1981. Gyda chaneuon fel 68 Guns a Where Were You Hiding When the Storm Broke, llenwasant stadiymau ym Mhrydain ac America a theithio gydag U2 a Bob Dylan. Yn 1989 rhyddhawyd Change, a hefyd yn Gymraeg fel Newid.",
    "Ar ôl wynebu canser ei hun, sefydlodd Sefydliad Love Hope Strength yn 2007, sydd wedi cofrestru miloedd o roddwyr bôn-gelloedd drwy gyngherddau ar gopaon mynyddoedd o Everest i’r Wyddfa. Roedd yn arwr roc Cymru ac yn y frwydr yn erbyn canser."]),
 P("phil-campbell", "modern", "b. 1961", "Phil Campbell", "Phil Campbell", "Guitarist of Motörhead", "Gitarydd Motörhead", "Phil_Campbell_(musician)", "music",
   "Pontypridd guitarist who played with Motörhead for over thirty years, and now leads his own band with his three sons.",
   "Gitarydd o Bontypridd a chwaraeodd gyda Motörhead am dros ddeng mlynedd ar hugain, ac sydd bellach yn arwain ei fand ei hun gyda’i dri mab.",
   ["Phil Campbell grew up in Pontypridd and was playing guitar in local bands as a teenager. In 1984 he joined Lemmy’s Motörhead, one of the loudest and most famous rock bands in the world.",
    "He stayed for thirty-one years, longer than any other guitarist, playing on more than a dozen albums and touring the world until Lemmy’s death in 2015. He then formed Phil Campbell and the Bastard Sons with his three sons, and keeps the flag of Welsh rock flying."],
   ["Magwyd Phil Campbell ym Mhontypridd ac roedd yn chwarae gitâr mewn bandiau lleol yn ei arddegau. Yn 1984 ymunodd â Motörhead Lemmy, un o fandiau roc uchaf a mwyaf enwog y byd.",
    "Arhosodd am un mlynedd ar ddeg ar hugain, yn hirach nag unrhyw gitarydd arall, gan chwarae ar dros ddwsin o albymau a theithio’r byd hyd farwolaeth Lemmy yn 2015. Ffurfiodd wedyn Phil Campbell and the Bastard Sons gyda’i dri mab, ac mae’n cadw baner roc Cymru i chwifio."]),
 P("simon-weston", "modern", "b. 1961", "Simon Weston", "Simon Weston", "Falklands hero", "Arwr y Falklands", "Simon_Weston", "heroes",
   "Welsh Guardsman from Nelson who survived terrible burns on the Sir Galahad in the Falklands War in 1982, and has inspired millions with his courage and his charity work.",
   "Milwr o’r Gwarchodlu Cymreig, o Nelson, a oroesodd losgiadau ofnadwy ar y Sir Galahad yn Rhyfel y Falklands yn 1982, ac sydd wedi ysbrydoli miliynau â’i ddewrder a’i waith elusennol.",
   ["Simon Weston grew up in Nelson in the Rhymney valley and joined the Welsh Guards at sixteen. On 8 June 1982 his ship, the Sir Galahad, was bombed at Bluff Cove in the Falklands. Forty-eight men died, twenty-two of them Welsh Guards, and Simon was left with burns to almost half his body.",
    "Through years of operations he fought his way back, and his story, told on television, moved the whole country. He co-founded the Weston Spirit charity for young people, has raised great sums for good causes and was made CBE. He remains one of the best-loved heroes of Wales."],
   ["Magwyd Simon Weston yn Nelson yng nghwm Rhymni ac ymunodd â’r Gwarchodlu Cymreig yn un ar bymtheg oed. Ar 8 Mehefin 1982 bomiwyd ei long, y Sir Galahad, ym Mae Bluff yn y Falklands. Bu farw wyth a deugain o ddynion, dau ar hugain ohonynt o’r Gwarchodlu Cymreig, a gadawyd Simon â llosgiadau dros bron i hanner ei gorff.",
    "Drwy flynyddoedd o lawdriniaethau ymladdodd ei ffordd yn ôl, a chyffyrddodd ei stori, a adroddwyd ar y teledu, â’r wlad gyfan. Cyd-sefydlodd yr elusen Weston Spirit i bobl ifanc, mae wedi codi symiau mawr at achosion da a’i wneud yn CBE. Mae’n parhau’n un o arwyr anwylaf Cymru."]),
 P("mark-hughes", "modern", "b. 1963", "Mark Hughes", "Mark Hughes", "Sparky", "Sparky", "Mark_Hughes", "sport",
   "Ruabon-born striker famous for his spectacular volleys for Manchester United and Wales, the first player to be named PFA Players’ Player of the Year twice, and later manager of Wales.",
   "Ymosodwr o Riwabon yn enwog am ei foleau syfrdanol i Fanchester United a Chymru, y chwaraewr cyntaf i’w enwi’n Chwaraewr y Flwyddyn y PFA ddwywaith, ac wedyn rheolwr Cymru.",
   ["Mark Hughes grew up in Ruabon near Wrexham and joined Manchester United as a boy. Strong, brave and able to score from impossible angles, ‘Sparky’ won two league titles and three FA Cups with United, and the European Cup Winners’ Cup in 1991, scoring both goals in the final against Barcelona, his old club.",
    "He was named PFA Players’ Player of the Year in 1989 and 1991, the first player to win it twice. He won 72 caps for Wales, and as manager from 1999 to 2004 he brought Wales to within one game of the European Championship finals."],
   ["Magwyd Mark Hughes yn Rhiwabon ger Wrecsam ac ymunodd â Manchester United yn fachgen. Yn gryf, yn ddewr ac yn gallu sgorio o onglau amhosibl, enillodd ‘Sparky’ ddwy bencampwriaeth a thri Chwpan FA gydag United, a Chwpan Enillwyr Cwpanau Ewrop yn 1991, gan sgorio’r ddwy gôl yn y rownd derfynol yn erbyn Barcelona, ei hen glwb.",
    "Fe’i henwyd yn Chwaraewr y Flwyddyn y PFA yn 1989 a 1991, y chwaraewr cyntaf i’w ennill ddwywaith. Enillodd 72 o gapiau dros Gymru, ac fel rheolwr o 1999 i 2004 daeth â Chymru o fewn un gêm i rowndiau terfynol Pencampwriaeth Ewrop."]),
 P("patrick-jones", "today", "b. 1965", "Patrick Jones", "Patrick Jones", "Poet and playwright of the valleys", "Bardd a dramodydd y cymoedd", "Patrick_Jones_(poet)", "words",
   "Blackwood poet, playwright and filmmaker whose fierce, tender work speaks for the valleys, and whose words have been sung by the Manic Street Preachers.",
   "Bardd, dramodydd a gwneuthurwr ffilmiau o’r Coed-duon y mae ei waith ffyrnig a thyner yn llefaru dros y cymoedd, ac y canwyd ei eiriau gan y Manic Street Preachers.",
   ["Patrick Jones grew up in Blackwood, the older brother of the Manics’ Nicky Wire. His play Everything Must Go (2000), set in a valleys town after the pits closed, was a hit at the Sherman Theatre in Cardiff.",
    "His poetry collections, plays and films speak up for working-class Wales, for its people and its pride. He has worked with the Manic Street Preachers and with musicians across Wales, and was voted one of the 100 Welsh Heroes."],
   ["Magwyd Patrick Jones yn y Coed-duon, yn frawd hŷn i Nicky Wire y Manics. Bu ei ddrama Everything Must Go (2000), a leolwyd mewn tref yn y cymoedd wedi i’r pyllau gau, yn llwyddiant yn Theatr y Sherman yng Nghaerdydd.",
    "Mae ei gasgliadau o gerddi, ei ddramâu a’i ffilmiau yn siarad dros Gymru’r dosbarth gweithiol, dros ei phobl a’i balchder. Mae wedi gweithio gyda’r Manic Street Preachers a cherddorion ledled Cymru, a phleidleisiwyd ef yn un o’r 100 Arwr Cymreig."]),
 P("richey-edwards", "modern", "b. 1967", "Richey Edwards", "Richey Edwards", "Lyricist of the Manic Street Preachers", "Telynegwr y Manic Street Preachers", "Richey_Edwards", "music",
   "Blackwood guitarist and lyricist of the Manic Street Preachers, whose brilliant, searching words on The Holy Bible made him an icon. He has been missing since 1995.",
   "Gitarydd a thelynegwr y Manic Street Preachers o’r Coed-duon, y gwnaeth ei eiriau disglair, chwilgar ar The Holy Bible ef yn eicon. Mae ar goll ers 1995.",
   ["Richey James Edwards grew up in Blackwood and studied political history at Swansea before joining his friends in the Manic Street Preachers. Clever, well read and stylish, he wrote many of the band’s lyrics.",
    "His words on the album The Holy Bible (1994) are counted among the most powerful in British rock. He went missing in February 1995, and the band honoured him by keeping his place: their album Journal for Plague Lovers (2009) is set entirely to his lyrics."],
   ["Magwyd Richey James Edwards yn y Coed-duon ac astudiodd hanes gwleidyddol yn Abertawe cyn ymuno â’i ffrindiau yn y Manic Street Preachers. Yn glyfar, yn ddarllengar ac yn steilus, ysgrifennodd lawer o eiriau’r band.",
    "Cyfrifir ei eiriau ar yr albwm The Holy Bible (1994) ymhlith y grymusaf ym myd roc Prydain. Aeth ar goll ym mis Chwefror 1995, ac anrhydeddodd y band ef drwy gadw ei le: mae eu halbwm Journal for Plague Lovers (2009) wedi’i gosod yn gyfan gwbl ar ei eiriau ef."]),
 P("james-dean-bradfield", "today", "b. 1969", "James Dean Bradfield", "James Dean Bradfield", "Singer of the Manic Street Preachers", "Canwr y Manic Street Preachers", "James_Dean_Bradfield", "music",
   "Singer and guitarist of the Manic Street Preachers from Pontllanfraith, whose voice carried A Design for Life and If You Tolerate This to the top of the charts.",
   "Canwr a gitarydd y Manic Street Preachers o Bontllan-fraith, y cariodd ei lais A Design for Life ac If You Tolerate This i frig y siartiau.",
   ["James Dean Bradfield grew up in Pontllanfraith near Blackwood, and formed the Manic Street Preachers with his cousin Sean Moore and schoolfriends Nicky Wire and Richey Edwards. He writes the band’s music and sings their songs.",
    "After A Design for Life (1996), with its line taken from the library at Pillgwenlly, the Manics became one of the biggest bands in Britain. If You Tolerate This Your Children Will Be Next, a song about the Welshmen who fought in the Spanish Civil War, went to number one in 1998, and they played the first concert of the new millennium at the Millennium Stadium."],
   ["Magwyd James Dean Bradfield ym Mhontllan-fraith ger y Coed-duon, a ffurfiodd y Manic Street Preachers gyda’i gefnder Sean Moore a’i ffrindiau ysgol Nicky Wire a Richey Edwards. Ef sy’n ysgrifennu cerddoriaeth y band ac yn canu eu caneuon.",
    "Ar ôl A Design for Life (1996), daeth y Manics yn un o fandiau mwyaf Prydain. Aeth If You Tolerate This Your Children Will Be Next, cân am y Cymry a ymladdodd yn Rhyfel Cartref Sbaen, i rif un yn 1998, a chwaraeasant gyngerdd cyntaf y mileniwm newydd yn Stadiwm y Mileniwm."]),
 P("julien-macdonald", "today", "b. 1971", "Julien Macdonald", "Julien Macdonald", "Fashion designer", "Cynllunydd ffasiwn", "Julien_Macdonald", "art",
   "Merthyr-born fashion designer, famous for glittering knitwear and red-carpet gowns, who succeeded Alexander McQueen as chief designer at Givenchy in Paris.",
   "Cynllunydd ffasiwn o Ferthyr, yn enwog am ei weuwaith disglair a’i ffrogiau carped coch, a olynodd Alexander McQueen yn brif gynllunydd Givenchy ym Mharis.",
   ["Julien Macdonald grew up in Merthyr Tydfil, where his mother taught him to knit and he learned tap dancing. He studied fashion at Brighton and the Royal College of Art, and Karl Lagerfeld hired him to design knitwear for Chanel.",
    "In 2001 he became chief designer at the Paris house of Givenchy and was named British Designer of the Year. His sparkling, daring gowns have been worn by stars around the world, and he has never hidden his pride in Merthyr."],
   ["Magwyd Julien Macdonald ym Merthyr Tudful, lle dysgodd ei fam iddo wau a dysgodd yntau ddawnsio tap. Astudiodd ffasiwn yn Brighton a’r Coleg Celf Brenhinol, a chyflogodd Karl Lagerfeld ef i gynllunio gweuwaith i Chanel.",
    "Yn 2001 daeth yn brif gynllunydd tŷ Givenchy ym Mharis a’i enwi’n Gynllunydd Prydeinig y Flwyddyn. Mae sêr ar draws y byd wedi gwisgo ei ffrogiau disglair, beiddgar, ac nid yw erioed wedi cuddio ei falchder ym Merthyr."]),
]

PEOPLE += [
 P("david-emanuel", "modern", "b. 1952", "David Emanuel", "David Emanuel", "Designer of the royal wedding dress", "Cynllunydd y ffrog briodas frenhinol", "David_Emanuel", "art",
   "Bridgend-born fashion designer who, with Elizabeth Emanuel, made the wedding dress of Diana, Princess of Wales, in 1981, one of the most famous dresses ever made.",
   "Cynllunydd ffasiwn o Ben-y-bont ar Ogwr a wnaeth, gydag Elizabeth Emanuel, ffrog briodas Diana, Tywysoges Cymru, yn 1981, un o ffrogiau enwocaf erioed.",
   ["David Emanuel grew up in Bridgend and studied fashion at Cardiff and the Royal College of Art, where he met Elizabeth Weiner, whom he married. Their romantic gowns of silk and taffeta soon drew famous clients.",
    "In 1981 they were chosen to design the wedding dress of Lady Diana Spencer, with its 25-foot train, watched by some 750 million people around the world. He has since dressed stars of stage and screen and become a familiar face on television."],
   ["Magwyd David Emanuel ym Mhen-y-bont ar Ogwr ac astudiodd ffasiwn yng Nghaerdydd a’r Coleg Celf Brenhinol, lle cyfarfu ag Elizabeth Weiner, a briododd. Denodd eu gynau rhamantus o sidan a thaffeta gwsmeriaid enwog yn fuan.",
    "Yn 1981 fe’u dewiswyd i gynllunio ffrog briodas yr Arglwyddes Diana Spencer, â’i chynffon 25 troedfedd, a wyliwyd gan ryw 750 miliwn o bobl ledled y byd. Ers hynny mae wedi gwisgo sêr y llwyfan a’r sgrin ac wedi dod yn wyneb cyfarwydd ar y teledu."]),
 P("ross-lovegrove", "today", "b. 1958", "Ross Lovegrove", "Ross Lovegrove", "Designer of organic forms", "Cynllunydd ffurfiau organig", "Ross_Lovegrove", "art",
   "Cardiff-born industrial designer, nicknamed Captain Organic, whose flowing designs, from the Ty Nant water bottle to chairs, cars and cameras, are shown in museums across the world.",
   "Cynllunydd diwydiannol o Gaerdydd, a lysenwyd yn Captain Organic, y dangosir ei gynlluniau llifeiriol, o botel ddŵr Tŷ Nant i gadeiriau, ceir a chamerâu, mewn amgueddfeydd ar draws y byd.",
   ["Ross Lovegrove was born in Cardiff and studied industrial design at Manchester and the Royal College of Art. He worked for Sony, Apple, Louis Vuitton and many others, designing everything from computers to furniture.",
    "His work is inspired by the shapes of nature and made with the newest technology. His rippling bottle for Ty Nant, the Welsh spring water, became a design classic, and his pieces are in the collections of the Museum of Modern Art in New York and the Centre Pompidou in Paris."],
   ["Ganed Ross Lovegrove yng Nghaerdydd ac astudiodd gynllunio diwydiannol ym Manceinion a’r Coleg Celf Brenhinol. Gweithiodd i Sony, Apple, Louis Vuitton a llawer eraill, gan gynllunio popeth o gyfrifiaduron i ddodrefn.",
    "Ysbrydolir ei waith gan ffurfiau natur a’i wneud â’r dechnoleg ddiweddaraf. Daeth ei botel donnog i Dŷ Nant, dŵr ffynnon Cymru, yn glasur cynllunio, ac mae ei ddarnau yng nghasgliadau’r Amgueddfa Celf Fodern yn Efrog Newydd a’r Centre Pompidou ym Mharis."]),
 P("kelly-jones", "today", "b. 1974", "Kelly Jones", "Kelly Jones", "Singer of the Stereophonics", "Canwr y Stereophonics", "Kelly_Jones", "music",
   "Cwmaman singer and songwriter whose gravelly voice has carried the Stereophonics to a string of number-one albums and the number-one single Dakota.",
   "Canwr a chyfansoddwr o Gwmaman y mae ei lais garw wedi cario’r Stereophonics i gyfres o albymau rhif un a’r sengl rif un Dakota.",
   ["Kelly Jones grew up in Cwmaman near Aberdare and formed the band that became the Stereophonics with his friends Richard Jones and Stuart Cable. Their first album, Word Gets Around (1997), told stories of valleys life.",
    "Hits such as Local Boy in the Photograph, Have a Nice Day and Maybe Tomorrow followed, and Dakota went to number one in 2005. They have had a run of number-one albums and have played to huge crowds at Morfa Stadium, Cardiff Castle and the Principality Stadium."],
   ["Magwyd Kelly Jones yng Nghwmaman ger Aberdâr a ffurfiodd y band a ddaeth yn Stereophonics gyda’i ffrindiau Richard Jones a Stuart Cable. Adroddai eu halbwm cyntaf, Word Gets Around (1997), straeon am fywyd y cymoedd.",
    "Dilynodd caneuon fel Local Boy in the Photograph, Have a Nice Day a Maybe Tomorrow, ac aeth Dakota i rif un yn 2005. Maent wedi cael cyfres o albymau rhif un ac wedi chwarae i dyrfaoedd enfawr yn Stadiwm Morfa, Castell Caerdydd a Stadiwm Principality."]),
 P("mark-williams-snooker", "today", "b. 1975", "Mark Williams", "Mark Williams", "Three-time snooker world champion", "Pencampwr snwcer y byd deirgwaith", "Mark_Williams_(snooker_player)", "sport",
   "Snooker player from Cwm near Ebbw Vale who won the World Championship in 2000, 2003 and 2018, and the sport’s Triple Crown in a single season.",
   "Chwaraewr snwcer o Gwm ger Glynebwy a enillodd Bencampwriaeth y Byd yn 2000, 2003 a 2018, a Choron Driphlyg y gamp mewn un tymor.",
   ["Mark Williams grew up in Cwm, a mining village near Ebbw Vale, and boxed as a boy before turning to snooker. A left-hander with a famously smooth long game, he won his first world title at the Crucible in 2000 by beating fellow Welshman Matthew Stevens.",
    "In the 2002–03 season he won the World Championship, the UK Championship and the Masters, the Triple Crown in one season, and was world number one. Fifteen years after his second title he won a third in 2018, among the oldest world champions, and he has stayed among the best players in the world for three decades."],
   ["Magwyd Mark Williams yng Nghwm, pentref glofaol ger Glynebwy, a bu’n bocsio yn fachgen cyn troi at snwcer. Yn chwaraewr llaw chwith â gêm hir esmwyth enwog, enillodd ei deitl byd cyntaf yn y Crucible yn 2000 drwy guro’i gyd-Gymro Matthew Stevens.",
    "Yn nhymor 2002–03 enillodd Bencampwriaeth y Byd, Pencampwriaeth y DU a’r Masters, y Goron Driphlyg mewn un tymor, a bu’n rhif un y byd. Bymtheng mlynedd ar ôl ei ail deitl enillodd drydydd yn 2018, ymhlith pencampwyr byd hynaf y gamp, ac mae wedi aros ymhlith chwaraewyr gorau’r byd am dri degawd."]),
 P("luke-evans", "today", "b. 1979", "Luke Evans", "Luke Evans", "Actor and singer", "Actor a chanwr", "Luke_Evans", "stage",
   "Pontypool-born actor and singer who went from West End musicals to Hollywood, as Gaston in Beauty and the Beast and Bard the Bowman in The Hobbit.",
   "Actor a chanwr o Bont-y-pŵl a aeth o sioeau cerdd y West End i Hollywood, fel Gaston yn Beauty and the Beast a Bard y Bwasaethwr yn The Hobbit.",
   ["Luke Evans was born in Pontypool and grew up in Aberbargoed. At seventeen he moved to Cardiff and then won a scholarship to the London Studio Centre, and he spent years singing in West End musicals such as Miss Saigon and Rent.",
    "Film brought him world fame: as Bard the Bowman in The Hobbit, in the Fast & Furious films and as a magnificent Gaston in Disney’s Beauty and the Beast (2017). He has also recorded albums of songs, and is a proud ambassador for Wales."],
   ["Ganed Luke Evans ym Mhont-y-pŵl a magwyd ef yn Aberbargod. Yn ddwy ar bymtheg symudodd i Gaerdydd ac yna enillodd ysgoloriaeth i’r London Studio Centre, a threuliodd flynyddoedd yn canu mewn sioeau cerdd y West End fel Miss Saigon a Rent.",
    "Daeth ffilm ag enwogrwydd byd-eang iddo: fel Bard y Bwasaethwr yn The Hobbit, yn ffilmiau Fast & Furious ac fel Gaston godidog yn Beauty and the Beast Disney (2017). Mae hefyd wedi recordio albymau o ganeuon, ac mae’n llysgennad balch dros Gymru."]),
 P("david-roberts-swimmer", "today", "b. 1980", "David Roberts", "David Roberts", "Eleven-time Paralympic champion", "Pencampwr Paralympaidd un ar ddeg o weithiau", "David_Roberts_(swimmer)", "sport",
   "Pontypridd swimmer who won eleven Paralympic gold medals between 2000 and 2008, equalling Tanni Grey-Thompson as Britain’s most successful Paralympian.",
   "Nofiwr o Bontypridd a enillodd un ar ddeg o fedalau aur Paralympaidd rhwng 2000 a 2008, gan gyfartalu â Tanni Grey-Thompson fel Paralympiad mwyaf llwyddiannus Prydain.",
   ["David Roberts was born in Pontypridd with cerebral palsy and took up swimming as a boy. At the Sydney Paralympics in 2000 he won four gold medals, and in Athens in 2004 four more.",
    "In Beijing in 2008 he won another four golds, bringing his total to eleven, the same as Tanni Grey-Thompson, and making them joint holders of the record for the most Paralympic golds won by a British athlete. He was made CBE."],
   ["Ganed David Roberts ym Mhontypridd â pharlys yr ymennydd a dechreuodd nofio yn fachgen. Yng Ngemau Paralympaidd Sydney yn 2000 enillodd bedair medal aur, ac yn Athen yn 2004 bedair arall.",
    "Yn Beijing yn 2008 enillodd bedair medal aur arall, gan ddod â’i gyfanswm i un ar ddeg, yr un fath â Tanni Grey-Thompson, a’u gwneud yn gyd-ddeiliaid y record am y nifer fwyaf o fedalau aur Paralympaidd a enillwyd gan athletwr o Brydain. Fe’i gwnaed yn CBE."]),
 P("duffy", "today", "b. 1984", "Duffy", "Duffy", "Singer of Mercy", "Cantores Mercy", "Duffy_(singer)", "music",
   "Singer from Nefyn whose album Rockferry was the best-selling album in Britain in 2008, winning a Grammy and three Brit Awards.",
   "Cantores o Nefyn; ei halbwm Rockferry oedd yr albwm a werthodd orau ym Mhrydain yn 2008, gan ennill Grammy a thair o wobrau Brit.",
   ["Aimée Anne Duffy grew up in Nefyn on the Llŷn peninsula, a Welsh speaker who sang in local bands. In 2003 she came second in the S4C talent show Wawffactor.",
    "Her soulful single Mercy went to number one in 2008, and her album Rockferry became the best-selling album in Britain that year. It won the Grammy for Best Pop Vocal Album and she won three Brit Awards, a dazzling success for a singer from Llŷn."],
   ["Magwyd Aimée Anne Duffy yn Nefyn ym Mhen Llŷn, yn siaradwraig Gymraeg a ganai mewn bandiau lleol. Yn 2003 daeth yn ail yn sioe dalent S4C Wawffactor.",
    "Aeth ei sengl soul Mercy i rif un yn 2008, a daeth ei halbwm Rockferry yr albwm a werthodd orau ym Mhrydain y flwyddyn honno. Enillodd y Grammy am yr Albwm Lleisiol Pop Gorau ac enillodd hithau dair o wobrau Brit, llwyddiant disglair i gantores o Lŷn."]),
 P("charlotte-church", "today", "b. 1986", "Charlotte Church", "Charlotte Church", "The Voice of an Angel", "Llais Angel", "Charlotte_Church", "music",
   "Cardiff singer whose first album, Voice of an Angel, made her a worldwide star at twelve. She went on to pop, television and campaigning.",
   "Cantores o Gaerdydd y gwnaeth ei halbwm cyntaf, Voice of an Angel, hi’n seren fyd-eang yn ddeuddeg oed. Aeth ymlaen at bop, teledu ac ymgyrchu.",
   ["Charlotte Church was discovered singing on television as a girl in Cardiff, and in 1998, at twelve, she released Voice of an Angel, which sold millions of copies around the world. She sang for presidents, popes and royalty, and on the soundtrack of the film A Beautiful Mind.",
    "As she grew up she turned to pop with songs such as Crazy Chick, hosted her own television show, and became an outspoken campaigner on social issues. She has sold over ten million records."],
   ["Darganfuwyd Charlotte Church yn canu ar y teledu’n ferch yng Nghaerdydd, ac yn 1998, yn ddeuddeg oed, rhyddhaodd Voice of an Angel, a werthodd filiynau o gopïau ledled y byd. Canodd i arlywyddion, pabau a brenhinoedd, ac ar drac sain y ffilm A Beautiful Mind.",
    "Wrth dyfu’n hŷn troes at bop gyda chaneuon fel Crazy Chick, cyflwynodd ei sioe deledu ei hun, a daeth yn ymgyrchydd huawdl ar faterion cymdeithasol. Mae wedi gwerthu dros ddeg miliwn o recordiau."]),
 P("taron-egerton", "today", "b. 1989", "Taron Egerton", "Taron Egerton", "Golden Globe-winning actor", "Actor a enillodd Golden Globe", "Taron_Egerton", "stage",
   "Actor raised in Anglesey and Aberystwyth who starred in the Kingsman films and won a Golden Globe for playing Elton John in Rocketman. His name, Taran, is Welsh for thunder.",
   "Actor a fagwyd ym Môn ac Aberystwyth a fu’n serennu yn ffilmiau Kingsman ac a enillodd Golden Globe am chwarae Elton John yn Rocketman. Daw ei enw, Taron, o’r gair Cymraeg taran.",
   ["Taron Egerton was born in 1989 and grew up in Llangefni on Anglesey and then in Aberystwyth, where he discovered acting in school plays and youth theatre. He trained at the Royal Academy of Dramatic Art in London.",
    "His big break came as Eggsy in Kingsman: The Secret Service (2014). In Rocketman (2019) he played Elton John and sang the songs himself, winning the Golden Globe for best actor in a musical. He loves to come home to the beach at Aberystwyth."],
   ["Ganed Taron Egerton yn 1989 a magwyd ef yn Llangefni ym Môn ac yna yn Aberystwyth, lle darganfu actio mewn dramâu ysgol a theatr ieuenctid. Hyfforddodd yn yr Academi Frenhinol Celf Ddramatig yn Llundain.",
    "Daeth ei gyfle mawr fel Eggsy yn Kingsman: The Secret Service (2014). Yn Rocketman (2019) chwaraeodd Elton John a chanu’r caneuon ei hun, gan ennill y Golden Globe am yr actor gorau mewn sioe gerdd. Mae wrth ei fodd yn dod adref i draeth Aberystwyth."]),
]

# From the WalesOnline list of the 50 greatest Welsh men and women (2016), and the near misses it names.
PEOPLE += [
 P("henry-v", "medieval", "1386–1422", "Henry V", "Harri o Fynwy", "The king born at Monmouth", "Y brenin a aned yn Nhrefynwy", "Henry_V_of_England", "rulers",
   "King of England born at Monmouth Castle, who won the battle of Agincourt in 1415 with an army in which Welsh archers played a famous part.",
   "Brenin Lloegr a aned yng Nghastell Trefynwy, a enillodd frwydr Agincourt yn 1415 gyda byddin y chwaraeodd saethwyr o Gymru ran enwog ynddi.",
   ["Henry was born in the gatehouse of Monmouth Castle in 1386, and was known as Harry of Monmouth all his life. He was made Prince of Wales in 1399 and king in 1413.",
    "In 1415 he invaded France, and at Agincourt his small, tired army won one of the most famous victories of the Middle Ages. Welsh archers and men-at-arms fought in it, among them Dafydd Gam of Brecon. Shakespeare’s Henry V tells his Welsh captain Fluellen: ‘For I am Welsh, you know, good countryman.’ His statue stands in the wall of Monmouth’s Shire Hall."],
   ["Ganed Harri ym mhorthdy Castell Trefynwy yn 1386, ac fe’i hadwaenid fel Harri o Fynwy ar hyd ei oes. Fe’i gwnaed yn Dywysog Cymru yn 1399 ac yn frenin yn 1413.",
    "Yn 1415 ymosododd ar Ffrainc, ac yn Agincourt enillodd ei fyddin fach flinedig un o fuddugoliaethau enwocaf yr Oesoedd Canol. Ymladdodd saethwyr a milwyr o Gymru ynddi, yn eu plith Dafydd Gam o Aberhonddu. Yn nrama Shakespeare mae Harri V yn dweud wrth ei gapten Cymreig Fluellen: ‘For I am Welsh, you know, good countryman.’ Saif ei gerflun ym mur Neuadd y Sir yn Nhrefynwy."]),
 P("lucy-thomas", "industrial", "1781–1847", "Lucy Thomas", "Lucy Thomas", "Mother of the Welsh steam coal trade", "Mam masnach glo ager Cymru", "Lucy_Thomas", "enterprise",
   "Merthyr widow who ran the Waun Wyllt colliery at Abercanaid and opened the London market to Welsh steam coal.",
   "Gweddw o Ferthyr a redodd lofa Waun Wyllt yn Abercanaid ac a agorodd farchnad Llundain i lo ager Cymru.",
   ["Lucy Thomas and her husband Robert opened a small coal level at Waun Wyllt, Abercanaid, near Merthyr Tydfil. When Robert died in 1833 she took charge of the business herself, at a time when almost no women ran pits.",
    "She sold her coal to the merchant George Insole of Cardiff, who shipped it to London, where it proved to burn hotter and cleaner than any other. It was the start of the great trade in Welsh steam coal that would power the world’s ships, and she has been called the mother of the Welsh steam coal trade."],
   ["Agorodd Lucy Thomas a’i gŵr Robert lefel glo fach yn Waun Wyllt, Abercanaid, ger Merthyr Tudful. Pan fu farw Robert yn 1833 cymerodd hi ofal o’r busnes ei hun, ar adeg pan nad oedd bron unrhyw fenywod yn rhedeg pyllau.",
    "Gwerthodd ei glo i’r masnachwr George Insole o Gaerdydd, a’i cludodd i Lundain, lle profodd i losgi’n boethach ac yn lanach nag unrhyw un arall. Dyna ddechrau’r fasnach fawr mewn glo ager Cymreig a fyddai’n gyrru llongau’r byd, ac fe’i galwyd yn fam masnach glo ager Cymru."]),
 P("david-griffiths-missionary", "industrial", "1792–1863", "David Griffiths", "David Griffiths", "Translator of the Malagasy Bible", "Cyfieithydd y Beibl Malagaseg", "David_Griffiths_(missionary)", "faith",
   "Welsh missionary who, with his fellow Welshman David Jones, gave Madagascar its written language and its first complete Bible, in 1835.",
   "Cenhadwr o Gymro a roddodd, gyda’i gyd-Gymro David Jones, iaith ysgrifenedig a’i Beibl cyflawn cyntaf i Fadagasgar, yn 1835.",
   ["David Griffiths trained at the academy at Neuaddlwyd in Ceredigion, and in 1820 sailed with the London Missionary Society to Madagascar, where his friend David Jones, also from Neuaddlwyd, had already begun work.",
    "The two Welshmen wrote down the Malagasy language in the Roman alphabet, opened schools across the capital, and translated the Bible. The complete Malagasy Bible was printed in 1835, one of the first in any African language. The people of Madagascar still honour the Welsh missionaries who gave them their written language."],
   ["Hyfforddodd David Griffiths yn academi Neuaddlwyd yng Ngheredigion, ac yn 1820 hwyliodd gyda Chymdeithas Genhadol Llundain i Fadagasgar, lle roedd ei gyfaill David Jones, hefyd o Neuaddlwyd, eisoes wedi dechrau gweithio.",
    "Ysgrifennodd y ddau Gymro yr iaith Falagaseg yn yr wyddor Rufeinig, agor ysgolion ar draws y brifddinas, a chyfieithu’r Beibl. Argraffwyd y Beibl Malagaseg cyflawn yn 1835, un o’r cyntaf mewn unrhyw iaith Affricanaidd. Mae pobl Madagasgar yn dal i anrhydeddu’r cenhadon o Gymru a roddodd iddynt eu hiaith ysgrifenedig."],
   first=("wales", "With David Jones, gave Madagascar its written language and first complete Bible", "Gyda David Jones, rhoddodd ei hiaith ysgrifenedig a’i Beibl cyflawn cyntaf i Fadagasgar", 1835)),
 P("gwendoline-margaret-davies", "modern", "1882–1951 and 1884–1963", "Gwendoline and Margaret Davies", "Gwendoline a Margaret Davies", "The sisters of Gregynog", "Chwiorydd Gregynog", "Gwendoline_and_Margaret_Davies", "art",
   "Sisters from Llandinam who gathered one of Britain’s great collections of Impressionist art and gave it to the people of Wales.",
   "Chwiorydd o Landinam a gasglodd un o gasgliadau mawr Prydain o gelf Argraffiadol a’i roi i bobl Cymru.",
   ["Gwendoline and Margaret Davies were granddaughters of David Davies of Llandinam, who built the Barry docks. From 1908 they spent their fortune on paintings, buying works by Monet, Renoir, Cézanne, Van Gogh and Rodin long before most British collectors dared to.",
    "In the First World War they ran canteens for soldiers in France, and afterwards made Gregynog Hall a centre for music, fine printing and learning. They left their great collection to the National Museum in Cardiff, where it is one of the treasures of Wales, and gave Gregynog to the University of Wales."],
   ["Wyresau i David Davies o Landinam, a gododd ddociau’r Barri, oedd Gwendoline a Margaret Davies. O 1908 gwariwyd eu ffortiwn ar luniau, gan brynu gweithiau gan Monet, Renoir, Cézanne, Van Gogh a Rodin ymhell cyn i’r rhan fwyaf o gasglwyr Prydain feiddio.",
    "Yn y Rhyfel Byd Cyntaf rhedent ffreuturau i filwyr yn Ffrainc, ac wedyn gwnaethant Neuadd Gregynog yn ganolfan cerddoriaeth, argraffu cain a dysg. Gadawsant eu casgliad mawr i’r Amgueddfa Genedlaethol yng Nghaerdydd, lle mae’n un o drysorau Cymru, a rhoddwyd Gregynog i Brifysgol Cymru."]),
 P("david-brunt", "modern", "1886–1965", "Sir David Brunt", "Syr David Brunt", "Father of modern weather science", "Tad gwyddor y tywydd fodern", "David_Brunt", "science",
   "Meteorologist from Montgomeryshire whose book Physical and Dynamical Meteorology (1934) helped found the modern science of weather.",
   "Meteorolegydd o Sir Drefaldwyn y bu ei lyfr Physical and Dynamical Meteorology (1934) yn gymorth i sefydlu gwyddor fodern y tywydd.",
   ["David Brunt was born at Staylittle in Montgomeryshire and grew up in Llanhilleth in Gwent, the son of a farm worker who became a miner. He won a place at Aberystwyth and then Cambridge, and in the First World War he forecast the weather for the army in France.",
    "He became the first professor of meteorology in Britain, at Imperial College, and his book Physical and Dynamical Meteorology was the first great textbook of the subject. The Brunt–Väisälä frequency, used by weather forecasters and ocean scientists everywhere, carries his name. He was knighted in 1949."],
   ["Ganed David Brunt yn Staylittle yn Sir Drefaldwyn a magwyd ef yn Llanhiledd yng Ngwent, yn fab i was fferm a ddaeth yn löwr. Enillodd le yn Aberystwyth ac yna Caergrawnt, ac yn y Rhyfel Byd Cyntaf bu’n darogan y tywydd i’r fyddin yn Ffrainc.",
    "Daeth yn athro meteoroleg yng Ngholeg Imperial, a’i lyfr Physical and Dynamical Meteorology oedd gwerslyfr mawr cyntaf y pwnc. Mae amledd Brunt–Väisälä, a ddefnyddir gan ddaroganwyr tywydd a gwyddonwyr y môr ym mhobman, yn dwyn ei enw. Fe’i gwnaed yn farchog yn 1949."]),
 P("martyn-lloyd-jones", "modern", "1899–1981", "Martyn Lloyd-Jones", "Martyn Lloyd-Jones", "The Doctor of Westminster Chapel", "Y Doctor", "Martyn_Lloyd-Jones", "faith",
   "Cardiff-born doctor who gave up a brilliant medical career to preach, first at Aberavon and then for thirty years at Westminster Chapel in London.",
   "Meddyg o Gaerdydd a roddodd y gorau i yrfa feddygol ddisglair i bregethu, yn gyntaf yn Aberafan ac yna am ddeng mlynedd ar hugain yng Nghapel Westminster yn Llundain.",
   ["Martyn Lloyd-Jones was born in Cardiff and grew up in Llangeitho in Ceredigion. He trained at St Bartholomew’s Hospital in London and became assistant to the king’s physician, with a great medical career ahead of him.",
    "In 1927 he gave it all up to become minister of a chapel at Sandfields, Aberavon, where his preaching filled the building. From 1939 to 1968 he preached at Westminster Chapel in London, and his sermons, printed in many volumes, are read all over the world. He was known simply as ‘the Doctor’."],
   ["Ganed Martyn Lloyd-Jones yng Nghaerdydd a magwyd ef yn Llangeitho yng Ngheredigion. Hyfforddodd yn Ysbyty St Bartholomew yn Llundain a daeth yn gynorthwyydd i feddyg y brenin, gyda gyrfa feddygol fawr o’i flaen.",
    "Yn 1927 rhoddodd y cyfan heibio i fod yn weinidog capel yn Sandfields, Aberafan, lle llenwai ei bregethu’r adeilad. O 1939 hyd 1968 pregethodd yng Nghapel Westminster yn Llundain, a darllenir ei bregethau, a argraffwyd mewn llawer cyfrol, ledled y byd. Fe’i hadwaenid yn syml fel ‘y Doctor’."]),
 P("jan-morris", "modern", "1926–2020", "Jan Morris", "Jan Morris", "Writer of places", "Awdur lleoedd", "Jan_Morris", "words",
   "Writer and proud Welsh patriot who sent the world the news of the first ascent of Everest in 1953, wrote some of the finest travel books of the century, and made her home at Llanystumdwy.",
   "Awdur a gwladgarwraig falch a anfonodd newyddion y dringo cyntaf ar Everest at y byd yn 1953, a ysgrifennodd rai o lyfrau teithio gorau’r ganrif, ac a wnaeth ei chartref yn Llanystumdwy.",
   ["Jan Morris, the child of a Welsh father, went with the 1953 British expedition to Everest as reporter for The Times, and her coded message about the first ascent reached London on the morning of the coronation.",
    "She wrote more than forty books, on Venice, Oxford, Trieste, the British Empire in the Pax Britannica trilogy, and Wales, which she loved above all. Her book Conundrum (1974) told the story of her transition. She lived for many years at Trefan Morys in Llanystumdwy and campaigned for Welsh independence."],
   ["Aeth Jan Morris, plentyn i dad o Gymro, gydag ymgyrch Brydeinig 1953 i Everest fel gohebydd The Times, a chyrhaeddodd ei neges gudd am y dringo cyntaf Lundain ar fore’r coroni.",
    "Ysgrifennodd dros ddeugain o lyfrau, am Fenis, Rhydychen, Trieste, yr Ymerodraeth Brydeinig yn y drioleg Pax Britannica, a Chymru, a garai’n fwy na’r cyfan. Adroddai ei llyfr Conundrum (1974) stori ei thrawsnewid. Bu’n byw am flynyddoedd lawer yn Nhrefan Morys yn Llanystumdwy ac ymgyrchodd dros annibyniaeth i Gymru."]),
 P("ralph-steadman", "today", "b. 1936", "Ralph Steadman", "Ralph Steadman", "Artist of splatter and ink", "Artist inc a sblash", "Ralph_Steadman", "art",
   "Cartoonist and illustrator who grew up in Abergele, famous for his wild ink drawings for Hunter S. Thompson’s Fear and Loathing in Las Vegas.",
   "Cartwnydd a darlunydd a fagwyd yn Abergele, yn enwog am ei luniau inc gwyllt i Fear and Loathing in Las Vegas Hunter S. Thompson.",
   ["Ralph Steadman was born in Wallasey and grew up in Abergele on the north Wales coast, where he went to grammar school. He began as a cartoonist for newspapers and magazines such as Punch and Private Eye.",
    "In 1970 he teamed up with the American writer Hunter S. Thompson, and his splattered, ferocious drawings for Fear and Loathing in Las Vegas became famous around the world. He has illustrated Alice in Wonderland, Treasure Island and Animal Farm, and his style is one of the most recognisable in modern art."],
   ["Ganed Ralph Steadman yn Wallasey a magwyd ef yn Abergele ar arfordir y gogledd, lle aeth i’r ysgol ramadeg. Dechreuodd fel cartwnydd i bapurau newydd a chylchgronau fel Punch a Private Eye.",
    "Yn 1970 ymunodd â’r awdur Americanaidd Hunter S. Thompson, a daeth ei luniau ffyrnig, sblashlyd ar gyfer Fear and Loathing in Las Vegas yn enwog ledled y byd. Mae wedi darlunio Alice in Wonderland, Treasure Island ac Animal Farm, ac mae ei arddull yn un o’r rhai mwyaf adnabyddus mewn celf fodern."]),
 P("philip-jones-griffiths", "modern", "1936–2008", "Philip Jones Griffiths", "Philip Jones Griffiths", "Photographer of the Vietnam War", "Ffotograffydd Rhyfel Fietnam", "Philip_Jones_Griffiths", "art",
   "Rhuddlan-born photographer whose book Vietnam Inc. (1971) showed the world the human cost of the Vietnam War. He was president of the Magnum agency.",
   "Ffotograffydd o Ruddlan y dangosodd ei lyfr Vietnam Inc. (1971) gost ddynol Rhyfel Fietnam i’r byd. Bu’n llywydd asiantaeth Magnum.",
   ["Philip Jones Griffiths was born in Rhuddlan and trained as a pharmacist, taking photographs in his spare time. He became a full-time photographer for The Observer and joined the great Magnum agency.",
    "From 1966 he spent years in Vietnam photographing the lives of ordinary people in the war. His book Vietnam Inc. (1971) is one of the most powerful records of war ever published. He was president of Magnum from 1980 to 1985, and his archive is now cared for in Wales."],
   ["Ganed Philip Jones Griffiths yn Rhuddlan a hyfforddodd fel fferyllydd, gan dynnu lluniau yn ei amser hamdden. Daeth yn ffotograffydd llawn amser i’r Observer ac ymunodd ag asiantaeth fawr Magnum.",
    "O 1966 treuliodd flynyddoedd yn Fietnam yn tynnu lluniau o fywydau pobl gyffredin yn y rhyfel. Mae ei lyfr Vietnam Inc. (1971) yn un o’r cofnodion grymusaf o ryfel a gyhoeddwyd erioed. Bu’n llywydd Magnum o 1980 hyd 1985, ac mae ei archif bellach yng ngofal Cymru."]),
 P("martin-evans", "today", "b. 1941", "Sir Martin Evans", "Syr Martin Evans", "Nobel prize for stem cells", "Gwobr Nobel am fôn-gelloedd", "Martin_Evans", "science",
   "Scientist who discovered embryonic stem cells in mice, and won the Nobel Prize for Medicine in 2007 while working at Cardiff University.",
   "Gwyddonydd a ddarganfu fôn-gelloedd embryonig mewn llygod, ac a enillodd Wobr Nobel am Feddygaeth yn 2007 tra’n gweithio ym Mhrifysgol Caerdydd.",
   ["Martin Evans studied at Cambridge and London, and in 1981 became one of the first to grow embryonic stem cells from mice in the laboratory. With them he found a way to change single genes in mice, so that scientists could study human diseases.",
    "He moved to Cardiff University in 1999, and in 2007 he shared the Nobel Prize in Physiology or Medicine for this work, the first Nobel prize won by a scientist working in Wales. He was knighted, and later became Chancellor of Cardiff University."],
   ["Astudiodd Martin Evans yng Nghaergrawnt a Llundain, ac yn 1981 roedd yn un o’r cyntaf i dyfu bôn-gelloedd embryonig o lygod yn y labordy. Gyda hwy cafodd ffordd i newid genynnau unigol mewn llygod, er mwyn i wyddonwyr astudio clefydau dynol.",
    "Symudodd i Brifysgol Caerdydd yn 1999, ac yn 2007 rhannodd Wobr Nobel mewn Ffisioleg neu Feddygaeth am y gwaith hwn, y wobr Nobel gyntaf a enillwyd gan wyddonydd yn gweithio yng Nghymru. Fe’i gwnaed yn farchog, ac yn ddiweddarach daeth yn Ganghellor Prifysgol Caerdydd."],
   first=("wales", "The first Nobel prize won by a scientist working in Wales", "Y wobr Nobel gyntaf a enillwyd gan wyddonydd yn gweithio yng Nghymru", 2007)),
 P("michael-moritz", "today", "b. 1954", "Sir Michael Moritz", "Syr Michael Moritz", "Backer of Google", "Cefnogwr Google", "Michael_Moritz", "enterprise",
   "Cardiff-born journalist turned investor who backed Google, Yahoo, PayPal and YouTube in their early days, and has given generously to education.",
   "Newyddiadurwr o Gaerdydd a droes yn fuddsoddwr ac a gefnogodd Google, Yahoo, PayPal a YouTube yn eu dyddiau cynnar, ac sydd wedi rhoi’n hael at addysg.",
   ["Michael Moritz was born in Cardiff in 1954 and went to school there before studying history at Oxford. He moved to America as a journalist for Time magazine, where he wrote one of the first books about Apple.",
    "In 1986 he joined the investment firm Sequoia Capital in Silicon Valley, and his early faith in Yahoo, Google, PayPal and YouTube made it one of the most successful in the world. He was knighted in 2013 and has given large sums to help young people from poorer homes go to university."],
   ["Ganed Michael Moritz yng Nghaerdydd yn 1954 ac aeth i’r ysgol yno cyn astudio hanes yn Rhydychen. Symudodd i America fel newyddiadurwr i gylchgrawn Time, lle ysgrifennodd un o’r llyfrau cyntaf am Apple.",
    "Yn 1986 ymunodd â’r cwmni buddsoddi Sequoia Capital yn Silicon Valley, a gwnaeth ei ffydd gynnar yn Yahoo, Google, PayPal a YouTube ef yn un o’r rhai mwyaf llwyddiannus yn y byd. Fe’i gwnaed yn farchog yn 2013 ac mae wedi rhoi symiau mawr i helpu pobl ifanc o gartrefi tlotach i fynd i’r brifysgol."]),
]
